package com.sky.controller.admin;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anySet;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.*;

import java.util.Collections;
import java.util.Set;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import com.sky.result.Result;
import com.sky.service.DishService;

import org.springframework.data.redis.core.RedisTemplate;
import org.springframework.data.redis.core.SetOperations;

@ExtendWith(MockitoExtension.class)
class DishControllerTest {

    @InjectMocks
    private DishController dishController;

    @Mock
    private DishService dishService;

    @Mock
    private RedisTemplate<String, Object> redisTemplate;

    @Test
    @DisplayName("正向测试：修复后startOrStop方法在正确路径变量下能正常工作")
    void testStartOrStop_WithCorrectPathVariable_ShouldWorkNormally() {
        // Arrange
        Integer status = 1;
        Long id = 1L;

        // Mock the RedisTemplate keys() method
        Set<String> cacheKeys = Collections.singleton("dish_1");
        when(redisTemplate.keys(anyString())).thenReturn(cacheKeys);
        when(redisTemplate.delete(any(Set.class))).thenReturn(1L);

        // Act
        Result<String> result = dishController.startOrStop(status, id);

        // Assert
        assertNotNull(result);
        assertEquals(1, result.getCode());

        // Verify service was called with correct parameters
        verify(dishService).startOrStop(status, id);
        verify(redisTemplate).keys(anyString());
        verify(redisTemplate).delete(any(Set.class));
    }

    @Test
    @DisplayName("边界测试：修复后，原来导致MissingPathVariableException的请求现在不再抛出异常")
    void testStartOrStop_OriginalMissingPathVariableException_ShouldNotThrow() {
        // Arrange
        Integer status = 0; // testing status=0 (disable)
        Long id = 2L;

        Set<String> cacheKeys = Collections.singleton("dish_2");
        when(redisTemplate.keys(anyString())).thenReturn(cacheKeys);
        when(redisTemplate.delete(any(Set.class))).thenReturn(1L);

        // Act & Assert - Should not throw MissingPathVariableException
        assertDoesNotThrow(() -> {
            Result<String> result = dishController.startOrStop(status, id);
            assertNotNull(result);
            assertEquals(1, result.getCode());
        });

        verify(dishService).startOrStop(status, id);
    }

    @Test
    @DisplayName("空值测试：当id参数为null时，方法应能正常处理而不抛出异常")
    void testStartOrStop_WithNullId_ShouldNotThrowException() {
        // Arrange
        Integer status = 1;
        Long id = null; // testing null id

        Set<String> cacheKeys = Collections.singleton("dish_*");
        when(redisTemplate.keys(anyString())).thenReturn(cacheKeys);
        when(redisTemplate.delete(any(Set.class))).thenReturn(1L);

        // Act & Assert
        assertDoesNotThrow(() -> {
            Result<String> result = dishController.startOrStop(status, id);
            assertNotNull(result);
            assertEquals(1, result.getCode());
        });

        verify(dishService).startOrStop(status, id);
    }

    @Test
    @DisplayName("Redis缓存清除测试：修复后应正确清除Redis缓存")
    void testStartOrStop_ShouldClearRedisCache() {
        // Arrange
        Integer status = 1;
        Long id = 1L;

        Set<String> cacheKeys = Collections.singleton("dish_1");
        when(redisTemplate.keys("dish_*")).thenReturn(cacheKeys);
        when(redisTemplate.delete(any(Set.class))).thenReturn(1L);

        // Act
        Result<String> result = dishController.startOrStop(status, id);

        // Assert
        assertEquals(1, result.getCode());

        // Verify Redis operations
        verify(redisTemplate).keys("dish_*");
        verify(redisTemplate).delete(cacheKeys);
    }
}
